import React, { useCallback, useEffect, useState } from 'react';
import {
  Box,
  Paper,
  Typography,
  Button,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  CircularProgress,
  Alert,
  Grid,
  Card,
  CardContent
} from '@mui/material';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import RefreshIcon from '@mui/icons-material/Refresh';
import documentService, { OcrBenchmarkReport, OcrBenchmarkSummary } from '../services/documentService';
import ScrollableTableContainer from './shared/ScrollableTableContainer';

const BenchmarkReports: React.FC = () => {
  const [reports, setReports] = useState<OcrBenchmarkReport[]>([]);
  const [latest, setLatest] = useState<OcrBenchmarkSummary | null>(null);
  const [loading, setLoading] = useState(false);
  const [running, setRunning] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [listRes, latestRes] = await Promise.all([
        documentService.getOcrBenchmarkReports(),
        documentService.getLatestOcrBenchmark().catch(() => null)
      ]);
      if (listRes.success) {
        setReports(listRes.reports);
      }
      if (latestRes?.success) {
        setLatest(latestRes.report);
      }
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to load benchmark reports');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const runBenchmark = async () => {
    setRunning(true);
    setError(null);
    try {
      const res = await documentService.runOcrBenchmark();
      if (res.success) {
        await load();
      }
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Benchmark run failed');
    } finally {
      setRunning(false);
    }
  };

  const fieldAccuracy = latest?.field_accuracy || {};

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6">OCR Benchmark Reports</Typography>
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Button startIcon={<RefreshIcon />} onClick={load} disabled={loading}>
            Refresh
          </Button>
          <Button
            variant="contained"
            startIcon={running ? <CircularProgress size={18} color="inherit" /> : <PlayArrowIcon />}
            onClick={runBenchmark}
            disabled={running}
          >
            Run benchmark
          </Button>
        </Box>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {latest && (
        <Grid container spacing={2} sx={{ mb: 3 }}>
          <Grid item xs={12} md={3}>
            <Card variant="outlined">
              <CardContent>
                <Typography variant="caption" color="text.secondary">
                  Cases run
                </Typography>
                <Typography variant="h5">{latest.cases_run ?? '—'}</Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={3}>
            <Card variant="outlined">
              <CardContent>
                <Typography variant="caption" color="text.secondary">
                  Mean OCR confidence
                </Typography>
                <Typography variant="h5">
                  {latest.mean_invoice_confidence != null
                    ? `${Math.round(latest.mean_invoice_confidence * 100)}%`
                    : '—'}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={3}>
            <Card variant="outlined">
              <CardContent>
                <Typography variant="caption" color="text.secondary">
                  GST accuracy
                </Typography>
                <Typography variant="h5">
                  {fieldAccuracy.gstin != null ? `${Math.round(fieldAccuracy.gstin * 100)}%` : '—'}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={3}>
            <Card variant="outlined">
              <CardContent>
                <Typography variant="caption" color="text.secondary">
                  Amount accuracy
                </Typography>
                <Typography variant="h5">
                  {fieldAccuracy.amount != null ? `${Math.round(fieldAccuracy.amount * 100)}%` : '—'}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      <Paper variant="outlined">
        <ScrollableTableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Report ID</TableCell>
                <TableCell>Created</TableCell>
                <TableCell>Cases</TableCell>
                <TableCell>Confidence</TableCell>
                <TableCell>Failures</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {reports.length === 0 && (
                <TableRow>
                  <TableCell colSpan={5} align="center">
                    {loading ? 'Loading…' : 'No benchmark reports yet. Run benchmark to generate.'}
                  </TableCell>
                </TableRow>
              )}
              {reports.map((r) => (
                <TableRow key={r.id}>
                  <TableCell>{r.id}</TableCell>
                  <TableCell>{r.createdAt ? new Date(r.createdAt).toLocaleString() : '—'}</TableCell>
                  <TableCell>{r.casesRun ?? '—'}</TableCell>
                  <TableCell>
                    {r.meanInvoiceConfidence != null
                      ? `${Math.round(r.meanInvoiceConfidence * 100)}%`
                      : '—'}
                  </TableCell>
                  <TableCell>{r.failedCount ?? 0}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </ScrollableTableContainer>
      </Paper>
    </Box>
  );
};

export default BenchmarkReports;
